"use client";
import { ArtemisScope } from "./artemis-scope";
import View1 from "./components/changelog-pages/variants/02-ledger";
const variants = {"ledger":View1};
export interface ArtemisChangelogProps { className?: string; variant?: "ledger"; }
export function ArtemisChangelog({ className, variant = "ledger" }: ArtemisChangelogProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import { AnimatePresence, motion, type Transition, useReducedMotion } from "motion/react";
import { useEffect, useRef, useState } from "react";
import { ArtemisButtonLink } from "../../../foundations/button";
import { ArtemisSegmentedTabs, ARTEMIS_TAB_LIST_PILL } from "../../../foundations/segmented-tabs";
import { ARTEMIS_SPRING_LAYOUT, ARTEMIS_SPRING_PANEL } from "../../../lib/ease";
type Category = "Product" | "Workflow" | "Connections";
type Filter = "all" | Category;
type Release = {
    id: string;
    title: string;
    date: string;
    category: Category;
    summary: string;
    points: readonly [
        string,
        string,
        string
    ];
    latest?: boolean;
};
const RELEASES: readonly Release[] = [
    {
        id: "release-4.8.0",
        title: "A canvas that keeps up with the room",
        date: "June 24, 2026",
        category: "Product",
        summary: "Working together on the same canvas now feels calmer. You can see where people are focused, follow a teammate, and keep every edit in step.",
        points: ["See where teammates are working", "Keep every edit in step", "Follow someone during a review"],
        latest: true,
    },
    {
        id: "release-4.7.2",
        title: "Repeat exports take one click",
        date: "June 10, 2026",
        category: "Workflow",
        summary: "Save the choices you use often and Workspace will remember the size, format, naming, and quality the next time around.",
        points: ["Save your usual export settings", "Prepare several files together", "Get smaller files with the same quality"],
    },
    {
        id: "release-4.7.0",
        title: "Bring your work together",
        date: "May 28, 2026",
        category: "Connections",
        summary: "Connect Workspace with the tools your team already uses, keep project details in sync, and choose exactly what each connection can see.",
        points: ["Share new work automatically", "Keep project details in sync", "Choose what each connection can access"],
    },
    {
        id: "release-4.6.4",
        title: "A calmer way to review work",
        date: "May 14, 2026",
        category: "Product",
        summary: "Review links now open in a focused presentation surface with pinned comments, resolved threads, and per-frame approvals.",
        points: ["Approve individual moments", "Invite guests without extra setup", "Keep resolved feedback out of the way"],
    },
];
const FILTERS = [
    { value: "all", label: "All" },
    { value: "Product", label: "Product" },
    { value: "Workflow", label: "Workflow" },
    { value: "Connections", label: "Connections" },
] as const;
const CARD_DELAY = 0.5;
const INSTANT: Transition = { duration: 0 };
const CARD_STAGGER = 0.06;
function isFilter(value: string): value is Filter {
    return FILTERS.some((f) => f.value === value);
}
function CheckIcon() {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-check art:size-3" aria-hidden="true">
      <path d="M20 6 9 17l-5-5"/>
    </svg>);
}
export default function ChangelogPagesLedger() {
    const [filter, setFilter] = useState<Filter>("all");
    const introDone = useRef(false);
    useEffect(() => {
        introDone.current = true;
    }, []);
    const reduce = useReducedMotion();
    const hero = (delay: number): Transition => (reduce ? INSTANT : { ...ARTEMIS_SPRING_PANEL, delay });
    const visible = RELEASES.filter((r) => filter === "all" || r.category === filter);
    return (<>
      <div className="art:min-h-screen art:w-full art:bg-background art:font-sans art:text-foreground">
        <main id="updates-top">
          <section className="art:mx-auto art:w-full art:max-w-5xl art:px-4 art:pt-16 art:pb-12 art:@min-[640px]/artemis:px-8 art:@min-[640px]/artemis:pt-24 art:@min-[640px]/artemis:pb-16">
            <motion.p className="art:font-medium art:text-muted-foreground art:text-sm" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={hero(0.08)}>
              {"Product updates"}
            </motion.p>
            <motion.h1 className="art:mt-4 art:max-w-3xl art:text-balance art:leading-[1.04] art:tracking-[-0.05em] art:text-4xl art:@min-[768px]/artemis:text-5xl art:font-medium" initial={{ opacity: 0, y: 14, filter: "blur(4px)" }} animate={{ opacity: 1, y: 0, filter: "blur(0px)" }} transition={hero(0.16)}>
              {"What\u2019s new, and why you\u2019ll notice."}
            </motion.h1>
            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={hero(0.27)}>
              <p className="art:mt-5 art:max-w-2xl art:text-pretty art:text-muted-foreground art:leading-7">
                {"A clear look at the improvements making Workspace easier, calmer, and more useful for everyday work."}
              </p>
              <div className="art:mt-8 art:flex art:flex-wrap art:items-center art:gap-x-4 art:gap-y-2 art:text-muted-foreground art:text-sm">
                <span>
                  {"Updated June 24"}
                </span>
                <span className="art:size-1 art:rounded-full art:bg-muted-foreground/40"/>
                <span>
                  {"New notes every few weeks"}
                </span>
              </div>
            </motion.div>
          </section>
          <section className="art:mx-auto art:w-full art:max-w-5xl art:px-4 art:pb-16 art:@min-[640px]/artemis:px-8 art:@min-[640px]/artemis:pb-24">
            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={hero(0.39)}>
              <div className="art:overflow-x-auto">
                <ArtemisSegmentedTabs items={FILTERS} value={filter} onValueChange={(v) => {
            if (isFilter(v))
                setFilter(v);
        }} listClassName={`${ARTEMIS_TAB_LIST_PILL} art:min-w-max`} buttonClassName="art:rounded-full art:min-h-8" ariaLabel="Filter product updates" layout="position"/>
              </div>
            </motion.div>
            <div className="art:mt-7 art:space-y-4">
              <AnimatePresence mode="popLayout">
                {visible.map((release, i) => (<motion.article key={release.id} id={release.id} className="art:rounded-2xl art:bg-background art:p-2" layout initial={{ opacity: 0, y: 16 }} animate={{
                opacity: 1,
                y: 0,
                transition: reduce ? INSTANT : { ...ARTEMIS_SPRING_LAYOUT, delay: introDone.current ? 0 : CARD_DELAY + i * CARD_STAGGER },
            }} exit={{ opacity: 0, y: -8 }} transition={reduce ? INSTANT : ARTEMIS_SPRING_LAYOUT}>
                    <div className="art:pt-1 art:px-1 art:flex art:flex-wrap">
                      <h2 className="art:max-w-2xl art:text-balance art:leading-tight art:tracking-[-0.035em] art:text-4xl art:font-medium">
                        {release.title}
                      </h2>
                      {filter === "all" && release.latest ? (<span className="art:ml-auto art:inline-flex art:rounded-full art:bg-[linear-gradient(110deg,#ff6b6b,#ffd166,#67c587,#5ca8ff,#c986e8,#ff6b9d)] art:p-[1.5px]">
                          <span className="art:rounded-full art:bg-background art:px-3 art:py-1 art:font-medium art:text-foreground art:text-xs">
                            {"Latest"}
                          </span>
                        </span>) : null}
                    </div>
                    <div className="art:bg-background art:mt-2 art:rounded-2xl art:p-3">
                      <div className="art:flex art:flex-wrap art:items-center art:gap-2 art:text-muted-foreground art:text-sm">
                        <span>
                          {release.date}
                        </span>
                        <span aria-hidden="true">
                          {"\u00B7"}
                        </span>
                        <span>
                          {release.category}
                        </span>
                      </div>
                      <p className="art:mt-4 art:max-w-3xl art:text-pretty art:text-muted-foreground art:leading-7">
                        {release.summary}
                      </p>
                      <ul className="art:mt-7 art:grid art:gap-3 art:@min-[640px]/artemis:grid-cols-3">
                        {release.points.map((point) => (<li key={point} className="art:flex art:items-start art:gap-2.5 art:text-sm art:leading-6">
                            <span className="art:mt-1 art:grid art:size-5 art:shrink-0 art:place-items-center art:rounded-full art:bg-muted art:text-foreground">
                              <CheckIcon />
                            </span>
                            {point}
                          </li>))}
                      </ul>
                    </div>
                  </motion.article>))}
              </AnimatePresence>
            </div>
          </section>
          <section id="updates-subscribe" className="art:px-4 art:pb-16 art:@min-[640px]/artemis:px-8 art:@min-[640px]/artemis:pb-24">
            <div className="art:mx-auto art:flex art:w-full art:max-w-5xl art:flex-col art:items-start art:justify-between art:gap-7 art:rounded-2xl art:border art:border-border/60 art:bg-background art:p-6 art:@min-[640px]/artemis:p-9 art:@min-[768px]/artemis:flex-row art:@min-[768px]/artemis:items-center">
              <div>
                <p className="art:text-muted-foreground art:text-sm">
                  {"A short monthly note"}
                </p>
                <h2 className="art:mt-2 art:max-w-xl art:text-balance art:tracking-[-0.035em] art:text-4xl art:font-medium">
                  {"Keep up with the changes worth knowing about."}
                </h2>
              </div>
              <ArtemisButtonLink href="#updates-top" size="lg">
                {"Subscribe"}
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-right art:size-4" aria-hidden="true">
                  <path d="M5 12h14"/>
                  <path d="m12 5 7 7-7 7"/>
                </svg>
              </ArtemisButtonLink>
            </div>
          </section>
        </main>
      </div>
    </>);
}
